<script setup lang="ts">import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{useTimeAttack}from'../composables/useTimeAttack';import{useI18n,locale}from'../i18n';import{shareText}from'../utils';const g=useTimeAttack(),{t}=useI18n(),router=useRouter(),menu=ref(false);onMounted(g.begin);function toggleMenu(){menu.value=!menu.value;g.pause()}function goHome(){if(g.status.value==='paused'||confirm(t.value('quit')))router.push('/home')}async function share(){await shareText(`FLAG STREAK ⚡\n🔥 ${g.score.value} ${t.value('flags')} in 60 secondi!`)}</script>
<template><section class="screen game time-attack" :class="g.status.value"><div v-if="g.status.value==='countdown'" class="countdown">{{g.countdown.value||'GO!'}}</div><template v-else-if="g.status.value!=='gameOver'"><header class="game-head"><button class="icon-btn home-btn" @click="goHome" :aria-label="t('home')">⌂</button><strong>🔥 {{g.score.value}}</strong><button class="icon-btn pause-btn" @click="toggleMenu" :aria-label="t('pause')">⏸</button><strong>⏱ {{g.time.value}}</strong></header><div class="timer" :class="{urgent:g.time.value<=10}"><span :style="{width:g.progress.value+'%'}"></span><b>-2s</b></div><div v-if="g.question.value" class="question"><div class="flag"><img :src="g.question.value.country.flagAsset" :alt="t('which')"></div><h2>{{t('which')}}</h2><div class="answers"><button v-for="a in g.question.value.answers" :key="a.code" :disabled="g.status.value!=='playing'" :class="{correct:g.status.value!=='playing'&&a.code===g.question.value.country.code,wrong:g.selected.value===a.code&&a.code!==g.question.value.country.code}" @click="g.answer(a)">{{a.names[locale]}}</button></div></div><div v-if="menu" class="modal"><div><h2>⏸ {{t('pause')}}</h2><button class="primary" @click="toggleMenu">{{t('resume')}}</button><button @click="router.push('/home')">⌂ {{t('home')}}</button></div></div></template><div v-else class="result"><div class="burst">⚡</div><h1>{{t('timeUp')}}</h1><p>{{t('guessed')}}</p><strong class="huge">{{g.score.value}} {{t('flags')}}</strong><div class="result-stats"><span>{{t('score')}}<b>{{g.score.value}}</b></span><span>{{t('record')}}<b>{{g.best.value}}</b></span></div><button class="primary" @click="g.begin">{{t('replay')}}</button><button @click="router.push('/home')">⌂ {{t('home')}}</button><button class="text-btn" @click="share">↗ {{t('share')}}</button></div></section></template>
